# Issue #206 follow-up — see scraper_grouped.py.j2's own identical
# HIDDEN_FIELD_NAMES/_tree_without_hidden_fields doc comments.
HIDDEN_FIELD_NAMES = set([])


# Returns a fresh tree with every HIDDEN_FIELD_NAMES-tagged element removed
# (recursively) — never mutates `el` in place, since hardening/change-
# detection (and, mid-construction, a combine/split transform's own sibling
# lookup) still need to see the full, unstripped tree. A no-op fast path
# when nothing is hidden — the common case — returns `el` itself unchanged.
def _tree_without_hidden_fields(el):
    if not HIDDEN_FIELD_NAMES:
        return el
    clone = ET.Element(el.tag, el.attrib)
    clone.text = el.text
    for child in el:
        if child.tag not in HIDDEN_FIELD_NAMES:
            clone.append(_tree_without_hidden_fields(child))
    return clone


# Issue #192: optional Output Blueprint field mapping — see
# scraper_grouped.py.j2's own identical BLUEPRINT_MAPPING doc comment
# (same reasoning, unconditional placement, and _flatten_group_tree_for_blueprint
# design — this is the Browser-engine mirror, only the two DOM-access calls
# differ, via _resolve_group_matches/_resolve_field_match below).
BLUEPRINT_MAPPING = []
BLUEPRINT_MAPPING_BY_SOURCE = {m["source"]: m["target"] for m in BLUEPRINT_MAPPING}


def _blueprint_subtree_has_mapped_field(node):
    if "children" in node:
        return any(_blueprint_subtree_has_mapped_field(child) for child in node["children"])
    return node["name"] in BLUEPRINT_MAPPING_BY_SOURCE


# Resolves one leaf field's raw value exactly like extract_group()'s own
# leaf branch — see scraper_grouped.py.j2's identical-in-spirit
# _resolve_flatten_leaf_value for the full "why a separate function"
# reasoning, including the Issue #213 note that Download is deliberately
# not applied here (a flattened Output Blueprint row keeps the raw URL), and
# the Issue #206 note that a combineFields/splitField transform has no
# sibling element to resolve against here either (see scraper_grouped.py.j2's
# own identical doc comment).
# Uses _resolve_field_match (defined further below, resolved lazily at
# call time — Python doesn't require def order to match call order) so
# FramePath-scoped fields work here exactly like they do for
# extract_group() itself.
def _resolve_flatten_leaf_value(page, scope, node):
    found = _resolve_field_match(page, scope, node)
    if node["mode"] == "exists":
        return "true" if found else "false"
    if found is None:
        return ""
    if node["mode"] == "attribute":
        return _apply_transforms(found.get_attribute(node["attribute"]) or "", node["transform"])
    if node["mode"] == "ownText":
        own_text = found.evaluate(
            "el => Array.from(el.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent).join('')"
        ).strip()
        return _apply_transforms(own_text, node["transform"])
    return _apply_transforms((found.text_content() or "").strip(), node["transform"])


# Flattens the group tree into denormalized rows for BLUEPRINT_MAPPING —
# see scraper_grouped.py.j2's identical _flatten_group_tree_for_blueprint
# for the full design reasoning (always returns a list of context dicts;
# only a relevant repeating group's own instance boundary ever multiplies
# it). `page` is threaded through purely for _resolve_group_matches/
# _resolve_field_match's own FramePath resolution, same as extract_group().
def _flatten_group_tree_for_blueprint(page, scope, node, context):
    if "children" in node:
        if not _blueprint_subtree_has_mapped_field(node):
            return [context]

        matches = _resolve_group_matches(page, scope, node)

        all_contexts = []
        for match in matches:
            instance_contexts = [context]
            for child in node["children"]:
                next_contexts = []
                for ctx in instance_contexts:
                    next_contexts.extend(_flatten_group_tree_for_blueprint(page, match, child, ctx))
                instance_contexts = next_contexts
            all_contexts.extend(instance_contexts)
        return all_contexts

    value = _resolve_flatten_leaf_value(page, scope, node)
    if node["name"] in BLUEPRINT_MAPPING_BY_SOURCE:
        return [{**context, node["name"]: value}]
    return [context]


# Issue #244: a second, tree-shaped Output Blueprint target schema — see
# scraper_grouped.py.j2's own identical-in-spirit BLUEPRINT_TREE_MAPPING/
# _build_blueprint_node doc comments for the full design reasoning. This is
# the Browser-engine mirror: the only real difference is that
# _blueprint_walk_suffix below delegates every step straight to
# _resolve_group_matches (already handling repeating/non-repeating AND
# FramePath uniformly, unlike the Static engine's own plain select/
# select_one pair), and every function threads `page` through for the same
# reason extract_group()/_flatten_group_tree_for_blueprint already do.
BLUEPRINT_TREE_MAPPING = []

_BLUEPRINT_GROUP_BY_NAME = {}
_BLUEPRINT_LEAF_BY_NAME = {}
_BLUEPRINT_PATH_BY_NAME = {}


def _blueprint_index_source_tree(nodes, ancestors):
    for node in nodes:
        if "children" in node:
            _BLUEPRINT_GROUP_BY_NAME.setdefault(node["name"], node)
            _BLUEPRINT_PATH_BY_NAME.setdefault(node["name"], ancestors)
            _blueprint_index_source_tree(node["children"], ancestors + [node])
        else:
            _BLUEPRINT_PATH_BY_NAME.setdefault(node["name"], ancestors)
            _BLUEPRINT_LEAF_BY_NAME.setdefault(node["name"], node)


_blueprint_index_source_tree(GROUPS, [])


def _blueprint_repeating_chain(name):
    return [g["name"] for g in _BLUEPRINT_PATH_BY_NAME.get(name, []) if g["repeating"]]


def _blueprint_full_path(name):
    ancestors = _BLUEPRINT_PATH_BY_NAME.get(name, [])
    group = _BLUEPRINT_GROUP_BY_NAME.get(name)
    return ancestors + [group] if group is not None else ancestors


def _blueprint_walk_suffix(page, scopes, suffix):
    for group in suffix:
        next_scopes = []
        for scope in scopes:
            next_scopes.extend(_resolve_group_matches(page, scope, group))
        scopes = next_scopes
    return scopes


# See scraper_grouped.py.j2's identical function for the full "trusts
# ScrapingPlanValidator's own generate-time guarantee, doesn't re-validate"
# reasoning.
def _blueprint_resolve_group_chain(target_children, ancestor_chain):
    chains = [_blueprint_repeating_chain(c["source"]) for c in target_children if "source" in c]
    non_empty = [c for c in chains if c]
    return max(non_empty, key=len) if non_empty else ancestor_chain


def _build_blueprint_node(page, top_scope, scope, ancestor_chain, ancestor_full_path, target_node):
    if "children" in target_node:
        row_chain = _blueprint_resolve_group_chain(target_node["children"], ancestor_chain)
        full_path = _blueprint_full_path(row_chain[-1]) if row_chain else ancestor_full_path
        instances = _blueprint_walk_suffix(page, [scope], full_path[len(ancestor_full_path):])

        elements = []
        for instance in instances:
            el = ET.Element(target_node["name"])
            for child in target_node["children"]:
                result = _build_blueprint_node(page, top_scope, instance, row_chain, full_path, child)
                if isinstance(result, list):
                    el.extend(result)
                else:
                    el.append(result)
            elements.append(el)
        return elements

    source_name = target_node["source"]
    leaf_node = _BLUEPRINT_LEAF_BY_NAME[source_name]
    chain = _blueprint_repeating_chain(source_name)
    if chain:
        scopes = _blueprint_walk_suffix(page, [scope], _blueprint_full_path(source_name)[len(ancestor_full_path):])
    else:
        scopes = _blueprint_walk_suffix(page, [top_scope], _blueprint_full_path(source_name))

    resolved = scopes[0] if scopes else None
    el = ET.Element(target_node["name"])
    el.text = ("false" if leaf_node["mode"] == "exists" else "") if resolved is None else _resolve_flatten_leaf_value(page, resolved, leaf_node)
    return el


def _build_blueprint_tree(page, target_roots):
    elements = []
    for target_node in target_roots:
        result = _build_blueprint_node(page, page, page, [], [], target_node)
        if isinstance(result, list):
            elements.extend(result)
        else:
            elements.append(result)
    return elements


# Issue #84: best-effort numeric normalization for a "toNumber" transform —
# finds the first numeric-looking substring and normalizes its decimal
# separator to '.', stripping thousands separators/currency symbols. When
# both '.' and ',' appear, the rightmost one is treated as the decimal point
# (handles both "1.234,56" and "1,234.56"); a single separator appearing more
# than once is treated as a thousands separator and stripped; a single
# separator appearing exactly once is treated as the decimal point (so
# "12,99"/"12.99" both work, at the cost of a genuinely ambiguous
# single-occurrence case like "1.234" always being read as 1.234, never as
# 1234 — chain a regex-extract transform first if that's not what's wanted).
# Empty string if nothing numeric is found.
def _to_number(value):
    match = re.search(r"-?\d[\d.,]*", value)
    if not match:
        return ""
    raw = match.group(0)
    last_dot = raw.rfind(".")
    last_comma = raw.rfind(",")
    if last_dot != -1 and last_comma != -1:
        decimal_pos = max(last_dot, last_comma)
        integer_part = raw[:decimal_pos].replace(".", "").replace(",", "")
        fractional_part = raw[decimal_pos + 1:]
        normalized = f"{integer_part}.{fractional_part}"
    elif raw.count(",") > 1 or raw.count(".") > 1:
        normalized = raw.replace(",", "").replace(".", "")
    else:
        normalized = raw.replace(",", ".")
    try:
        numeric = float(normalized)
    except ValueError:
        return ""
    return str(int(numeric)) if numeric.is_integer() else str(numeric)


# Issue #205: safe, explicit type-conversion transforms -- unlike toNumber's
# best-effort heuristic extraction, these either produce a well-formed value
# or fall back to their own clearly defined "onError" behavior
# ("KeepOriginal" leaves the pre-conversion value untouched, "UseDefault"
# substitutes the transform's own configured "defaultValue") rather than
# silently guessing.
_DATE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"(?P<yyyy>\d{4})", "mm": r"(?P<mm>\d{1,2})", "dd": r"(?P<dd>\d{1,2})"}


def _type_conversion_fallback(value, on_error, default_value):
    return default_value if on_error == "UseDefault" else value


def _to_integer(value, on_error, default_value):
    stripped = value.strip()
    if re.fullmatch(r"[+-]?\d+", stripped):
        return str(int(stripped))
    return _type_conversion_fallback(value, on_error, default_value)


def _to_boolean(value, on_error, default_value):
    normalized = value.strip().lower()
    if normalized in ("true", "1", "yes", "y"):
        return "True"
    if normalized in ("false", "0", "no", "n"):
        return "False"
    return _type_conversion_fallback(value, on_error, default_value)


# source_format is the same "{yyyy}"/"{mm}"/"{dd}" mini-template
# RangeSource.Format (RangeFormat.cs) already uses for ISO week/date
# parameters, compiled into a regex the same way (escape the literal
# template, then substitute each placeholder for its own capture group) so a
# format string valid on the companion side parses identically here. Also
# rejects a structurally-matching but non-existent calendar date (e.g.
# "2026-02-30") via date()'s own ValueError, not just a pattern match.
def _to_date(value, source_format, on_error, default_value):
    pattern = re.escape(source_format)
    for token, token_pattern in _DATE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), token_pattern)
    match = re.fullmatch(pattern, value.strip())
    if match:
        try:
            return date(int(match.group("yyyy")), int(match.group("mm")), int(match.group("dd"))).isoformat()
        except ValueError:
            pass
    return _type_conversion_fallback(value, on_error, default_value)


# Issue #234: strict price/currency conversion. number_format is one of
# ToCurrencyTransform.SupportedFormats, each written as its own example
# amount — its first punctuation mark is the thousands separator, its last
# the decimal separator (a space format also accepts no-break/narrow
# no-break spaces, the apostrophe format a typographic apostrophe). Finds
# the first number in the value (a separator only counts when a digit
# follows, so a trailing "." or "," after the amount is never swallowed),
# requires it to match the format strictly (thousands groups of exactly
# three digits, at most one decimal separator), and keeps the fraction
# digits exactly as scraped — no float rounding. Mirrored by
# toCurrencyPreview in extension/popup/field-transforms.js.
_CURRENCY_FORMATS = {
    "1.234,56": (",", "."),
    "1,234.56": (".", ","),
    "1 234,56": (",", "   "),
    "1'234.56": (".", "'’"),
}


def _to_currency(value, number_format, on_error, default_value):
    decimal_sep, thousands_seps = _CURRENCY_FORMATS.get(number_format, _CURRENCY_FORMATS["1.234,56"])
    candidate = re.search(r"[+-]?[0-9](?:[0-9]|[" + re.escape(decimal_sep + thousands_seps) + r"](?=[0-9]))*", value)
    if candidate:
        thousands = "[" + re.escape(thousands_seps) + "]"
        match = re.fullmatch(
            r"([+-]?)([0-9]{1,3}(?:" + thousands + r"[0-9]{3})+|[0-9]+)(?:" + re.escape(decimal_sep) + r"([0-9]+))?",
            candidate.group(0),
        )
        if match:
            integer = str(int(re.sub(thousands, "", match.group(2))))
            sign = "-" if match.group(1) == "-" else ""
            return sign + integer + ("." + match.group(3) if match.group(3) else "")
    return _type_conversion_fallback(value, on_error, default_value)


# Applies a field's ordered transform chain — each step's output feeds the
# next step's input, in the order the user configured them in.
# Issue #206: looks up another field's own already-computed value for
# CombineFieldsTransform/SplitFieldTransform. `siblings` is whatever
# representation the calling shape already has on hand at this point in
# extraction — a plain dict for flat/API-flat mode's in-progress row, or the
# in-construction parent ET.Element for container/API-tree mode (only that
# element's own direct children are considered, i.e. only siblings under the
# very same immediate parent group — see ScrapingPlanValidator's
# ValidateFieldTransformOrdering for why this is guaranteed to already be
# populated for a valid config). Missing/not-yet-computed simply resolves to
# "" rather than raising, the same "don't fail the whole row/element over
# one field" spirit every other transform here already follows.
def _resolve_transform_sibling(siblings, name):
    if siblings is None:
        return ""
    if isinstance(siblings, dict):
        return siblings.get(name, "")
    found = siblings.find(name)
    return (found.text or "") if found is not None else ""


def _apply_transforms(value, transforms, siblings=None):
    for t in transforms:
        kind = t["kind"]
        if kind == "trim":
            value = value.strip()
        elif kind == "regexExtract":
            match = re.search(t["pattern"], value)
            if match:
                try:
                    value = match.group(t.get("group", 0)) or ""
                except (IndexError, re.error):
                    value = ""
            else:
                value = ""
        elif kind == "replace":
            value = value.replace(t["find"], t["replacement"])
        elif kind == "toNumber":
            value = _to_number(value)
        elif kind == "toInteger":
            value = _to_integer(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toBoolean":
            value = _to_boolean(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toDate":
            value = _to_date(value, t.get("sourceFormat", "{yyyy}-{mm}-{dd}"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toCurrency":
            value = _to_currency(value, t.get("format", "1.234,56"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "combineFields":
            value = t.get("separator", " ").join(_resolve_transform_sibling(siblings, n) for n in t.get("sourceFieldNames", []))
        elif kind == "splitField":
            parts = _resolve_transform_sibling(siblings, t.get("sourceFieldName", "")).split(t.get("separator", " "))
            idx = t.get("index", 0)
            value = parts[idx] if 0 <= idx < len(parts) else ""
    return value


def _resolve_frame_locator(page, frame_path):
    scope = page
    for frame_selector in frame_path:
        scope = scope.frame_locator(frame_selector)
    return scope


# Used by the WaitFor/Fill/Click/Scroll action fragments rendered into the
# scrape() body below (one per playwright_*_step.py.j2 template) — a plain
# page.locator(selector) when frame_path is unset, a frame-scoped Locator
# otherwise. Page has .locator() too, so _resolve_frame_locator(page, [])
# returning page unchanged already makes this uniform without a separate
# branch here.
def _resolve_locator(page, selector, frame_path):
    return _resolve_frame_locator(page, frame_path or []).locator(selector)


def _resolve_group_matches(page, scope, node):
    frame_path = node.get("frame_path")
    if not frame_path:
        if node["repeating"]:
            return scope.query_selector_all(node["selector"])
        found = scope.query_selector(node["selector"])
        return [found] if found else []

    locator = _resolve_frame_locator(page, frame_path).locator(node["selector"])
    if node["repeating"]:
        return [item.element_handle() for item in locator.all()]
    return [locator.first.element_handle()] if locator.count() > 0 else []


def _resolve_field_match(page, scope, node):
    # Issue #206 follow-up: a derived (combineFields/splitField) field has
    # no selector of its own — see scraper_grouped.py.j2's own identical
    # guard.
    if not node["selector"]:
        return None
    frame_path = node.get("frame_path")
    if not frame_path:
        return scope.query_selector(node["selector"])

    locator = _resolve_frame_locator(page, frame_path).locator(node["selector"])
    return locator.first if locator.count() > 0 else None


# Same tree walk as the Static engine's scraper_grouped.py.j2 — only the two
# DOM-access calls differ (query_selector_all/query_selector here vs.
# select/select_one there), the recursive group/data-field logic is
# identical. `page` is threaded through explicitly (rather than relying on
# closure capture) purely so frame_path resolution — always relative to the
# top-level page, never to `scope` — has something to resolve from
# regardless of how deep the current recursion already is.
def extract_group(page, scope, node, siblings=None):
    if "children" in node:
        matches = _resolve_group_matches(page, scope, node)

        elements = []
        for match in matches:
            el = ET.Element(node["name"])
            # Issue #206: el is this group instance's own in-construction
            # element — see scraper_grouped.py.j2's own identical doc
            # comment on this same pattern.
            for child in node["children"]:
                result = extract_group(page, match, child, el)
                if isinstance(result, list):
                    el.extend(result)
                else:
                    el.append(result)
            elements.append(el)
        return elements

    el = ET.Element(node["name"])
    # Issue #206 follow-up: see scraper_grouped.py.j2's own identical doc
    # comment — a derived field's whole value comes from this call, so it
    # must always run through _apply_transforms rather than short-circuiting
    # to "" the way an ordinary missing-match does below.
    if not node["selector"]:
        el.text = "false" if node["mode"] == "exists" else _apply_transforms("", node["transform"], siblings)
        return el
    found = _resolve_field_match(page, scope, node)
    if node["mode"] == "exists":
        el.text = "true" if found else "false"
    elif found is None:
        el.text = ""
    elif node["mode"] == "attribute":
        value = _apply_transforms(found.get_attribute(node["attribute"]) or "", node["transform"], siblings)
        # Issue #213: see scraper_grouped.py.j2's own identical doc comment —
        # applied after transforms, replaces the raw URL with its own
        # downloaded local file path.
        el.text = _download_resource(page, value, node.get("maxDownloadSizeBytes"), node.get("allowedContentTypes")) if node.get("download") and value else value
    elif node["mode"] == "ownText":
        # Direct text-node children only, excluding any nested element's own
        # text — see scraper_grouped.py.j2's own doc comment on this same
        # branch for the "why" (a badge inside a name heading, etc.).
        # ElementHandle has no built-in "own text" accessor, unlike
        # BeautifulSoup's .contents, so this needs a small evaluate() call.
        own_text = found.evaluate(
            "el => Array.from(el.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent).join('')"
        ).strip()
        el.text = _apply_transforms(own_text, node["transform"], siblings)
    else:
        el.text = _apply_transforms((found.text_content() or "").strip(), node["transform"], siblings)
    return el










def scrape(url):
    with sync_playwright() as p:
        browser = p.chromium.launch()
        _session_exists = os.path.exists(SESSION_STATE_PATH)
        context = browser.new_context(storage_state=SESSION_STATE_PATH if _session_exists else None)
        page = context.new_page()
        _goto_checked(page, url)
        if not _session_exists:
            _resolve_locator(page, "form#login", None).wait_for(timeout=15000)
            _resolve_locator(page, "#user", None).fill(_require_env("SITE_USERNAME"))
            _resolve_locator(page, "#password", None).fill(_require_env("SITE_PASSWORD"))
            _resolve_locator(page, "button.login", None).first.click()
            _resolve_locator(page, ".account", None).wait_for(timeout=10000)

        # Multiple top-level groups are siblings in GROUPS, but XML needs
        # exactly one root element — wrap them all (across every paginated
        # page from this start URL, see below) in a single <Ergebnis>.
        root = ET.Element("Ergebnis")
        blueprint_rows = []
        blueprint_tree_elements = []
        page_number = 1
        while True:
            page_elements = []
            for node in GROUPS:
                page_elements.extend(extract_group(page, page, node))
            if not page_elements:
                break
            for el in page_elements:
                root.append(el)

            break

        context.storage_state(path=SESSION_STATE_PATH)
        browser.close()
        return root, blueprint_rows, blueprint_tree_elements


# Issue #319: a failed page request ends in one clean, actionable
# "ERROR: <what> to <url> failed: <detail>" line on stderr and a dedicated
# exit code instead of a raw requests/Playwright traceback — the same shape
# API mode has had since Issue #220 (PythonScriptVerifier.CleanScriptError
# turns such a line into /generate's error text). The hints say what to do
# about the status instead of only repeating it.
EXIT_REQUEST_FAILED = 7


def _request_failed(what, url, detail):
    print(f"ERROR: {what} to {url} failed: {detail}", file=sys.stderr)
    sys.exit(EXIT_REQUEST_FAILED)


def _http_error_detail(status_code):
    if status_code in (401, 403):
        reason = "Unauthorized" if status_code == 401 else "Forbidden"
        return (f"HTTP {status_code} ({reason}). The site refuses this script — it either requires a login "
                f"or blocks automated requests. If a login is needed, use the Browser engine with a login flow "
                f"or send a custom request header (e.g. Cookie or Authorization).")
    if status_code == 404:
        return "HTTP 404 (Not Found). The page doesn't exist (any more) — check the start URL."
    if status_code == 429:
        return ("HTTP 429 (Too Many Requests). The site is rate-limiting this script — enable "
                "\"Pause between requests\" or try again later.")
    if status_code >= 500:
        return (f"HTTP {status_code}. The site's server reported an error — this is usually temporary; "
                f"try again later or enable \"Retry on transient errors\".")
    return f"HTTP {status_code}."


# Navigates to `url`. Unlike requests, page.goto() doesn't raise on an HTTP
# error status (it hands back the error page, which then silently yields "no
# data"), and a navigation timeout/network error is a Playwright exception —
# both become one clean error line instead. A page.goto() that returns None
# (e.g. a same-document navigation) has no status to check.
def _goto_checked(page, url):
    try:
        response = page.goto(url, wait_until="load", timeout=30000)
    except Exception as e:
        # Playwright's message starts with the useful part ("Page.goto:
        # net::ERR_CONNECTION_REFUSED at ..." / "Timeout 30000ms exceeded");
        # the rest is a multi-line call log.
        reason = (str(e).splitlines() or [e.__class__.__name__])[0]
        _request_failed("Navigation", url, f"could not load the page ({reason}).")
    if response is not None and response.status >= 400:
        _request_failed("Navigation", url, _http_error_detail(response.status))
    return response




# Issue #291: the XML 1.0 spec only allows tab, LF, CR and characters from
# U+0020 on (minus the surrogate range and U+FFFE/U+FFFF) — a control character
# such as the BEL (U+0007) is illegal even as a character reference, so there
# is no way to write it. Python's xml.etree.ElementTree does not check that and
# would serialize it raw, producing a file no conforming XML parser accepts
# (the companion's own trial-run check included). Such characters are removed
# from every element's text right before the tree is written as XML; JSON and
# CSV output don't need this (json.dump escapes them, CSV has no restriction).
_ILLEGAL_XML_CHARS_RE = re.compile("[\x00-\x08\x0b\x0c\x0e-\x1f\ud800-\udfff￾￿]")


def _strip_illegal_xml_chars(root):
    for element in root.iter():
        if element.text:
            element.text = _ILLEGAL_XML_CHARS_RE.sub("", element.text)
        if element.tail:
            element.tail = _ILLEGAL_XML_CHARS_RE.sub("", element.tail)
def main():
    # Issue #83: each URL's own scrape() already wraps its matches in an
    # <Ergebnis> element (see above) — combine every URL's children into one
    # final <Ergebnis>, the same sibling-merging pattern already used for
    # multiple root groups from a single URL.
    root = ET.Element("Ergebnis")
    blueprint_rows = []
    blueprint_tree_elements = []
    all_urls = URLS
    for url in all_urls:
        page_root, page_blueprint_rows, page_blueprint_tree_elements = scrape(url)
        for el in page_root:
            root.append(el)
        blueprint_rows.extend(page_blueprint_rows)
        blueprint_tree_elements.extend(page_blueprint_tree_elements)
    # Issue #206 follow-up: writes a HIDDEN_FIELD_NAMES-stripped copy — count
    # and every use of `root` below (hardening, change detection) still see
    # the full, unstripped tree.
    output_root = _tree_without_hidden_fields(root)
    tree = ET.ElementTree(output_root)
    _strip_illegal_xml_chars(tree.getroot())
    ET.indent(tree)
    tree.write(OUTPUT_PATH, encoding="utf-8", xml_declaration=True)
    count = len(root.findall(".//*"))
    print(f"Done — {count} elements written to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
